import { useState } from "react";

import { apiPost } from "@/lib/apiClient";
import useApi from "@/hooks/useApi";
import ModuleIcon from "./ModuleIcon";
import { DemoBadge, ModuleButton, SelectField } from "./ModuleShared";

/**
 * Sensor Simulator (DEMO mode).
 *
 * Drives the ML pipeline without physical hardware. Two clearly separated
 * sources can be viewed here:
 *
 *   • DEMO DATA        — generated by POST /api/simulator/readings, always
 *                        labelled and never presented as hardware.
 *   • Connected sensors — real rows read from GET /api/sensor-readings
 *                        (?source=real). Demo rows are excluded from this view.
 *
 * Generated readings can optionally be *stored* (opt-in) — the backend always
 * writes them with `is_demo = true`, so they can never be confused with, or
 * overwrite, a real device's records. The same channel payload is what an
 * ESP32/ESP8266 node would POST to /api/sensor-readings/ingest.
 */
export default function SensorSimulator() {
  const { data: config } = useApi("/api/simulator/config");
  const channels = config?.channels ?? {};

  const [mode, setMode] = useState("demo");

  // Demo controls
  const [overrides, setOverrides] = useState({});
  const [failed, setFailed] = useState([]);
  const [noise, setNoise] = useState("0");
  const [seed, setSeed] = useState("");
  const [reading, setReading] = useState(null);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState(null);

  // Persist controls
  const [persistDeviceId, setPersistDeviceId] = useState("");
  const [persisting, setPersisting] = useState(false);
  const [persistNote, setPersistNote] = useState(null);
  const devicesData = useApi("/api/devices");
  const devices = devicesData.data?.items ?? [];

  // Real (connected-sensor) view
  const realData = useApi(mode === "real" ? "/api/sensor-readings?source=real" : null);
  const realReadings = realData.data?.items ?? [];

  const setOverride = (channel, value) =>
    setOverrides((prev) => ({ ...prev, [channel]: value }));

  const toggleFail = (channel) =>
    setFailed((prev) =>
      prev.includes(channel) ? prev.filter((c) => c !== channel) : [...prev, channel]
    );

  const generate = async () => {
    setGenerating(true);
    setError(null);
    setPersistNote(null);
    try {
      const cleanOverrides = {};
      for (const [channel, value] of Object.entries(overrides)) {
        if (value !== "" && value != null) cleanOverrides[channel] = Number(value);
      }
      const body = {
        overrides: cleanOverrides,
        fail: failed,
        noise: Number(noise) || 0,
        ...(seed !== "" ? { seed: Number(seed) } : {}),
      };
      const data = await apiPost("/api/simulator/readings", body);
      setReading(data);
    } catch (err) {
      setError(err.message || "Could not generate a demo reading.");
    } finally {
      setGenerating(false);
    }
  };

  const persist = async () => {
    if (!persistDeviceId) {
      setPersistNote({ tone: "error", text: "Choose a device to store the demo reading against." });
      return;
    }
    setPersisting(true);
    setPersistNote(null);
    try {
      const cleanOverrides = {};
      for (const [channel, value] of Object.entries(overrides)) {
        if (value !== "" && value != null) cleanOverrides[channel] = Number(value);
      }
      const data = await apiPost("/api/simulator/readings", {
        overrides: cleanOverrides,
        fail: failed,
        noise: Number(noise) || 0,
        ...(seed !== "" ? { seed: Number(seed) } : {}),
        persist: true,
        device_id: persistDeviceId,
      });
      setReading(data);
      setPersistNote({
        tone: "ok",
        text: `Stored as DEMO row ${data.record_id}. It is marked is_demo and is not a hardware reading.`,
      });
    } catch (err) {
      setPersistNote({ tone: "error", text: err.message || "Could not store the demo reading." });
    } finally {
      setPersisting(false);
    }
  };

  return (
    <div className="space-y-4">
      {/* Source switch */}
      <div className="flex items-center justify-between">
        <DemoBadge status={mode === "demo" ? "Demo data" : "Connected sensors"} />
        <div className="flex rounded-xl border border-[#DDE6DF] bg-white p-0.5">
          {[
            ["demo", "Demo data"],
            ["real", "Connected sensors"],
          ].map(([key, label]) => (
            <button
              key={key}
              onClick={() => setMode(key)}
              className={`rounded-[10px] px-3 py-1.5 text-[10px] font-extrabold transition ${
                mode === key ? "bg-[#216B45] text-white" : "text-[#52675B]"
              }`}
            >
              {label}
            </button>
          ))}
        </div>
      </div>

      {mode === "demo" ? (
        <>
          <p className="rounded-2xl bg-[#FFF5DE] p-3 text-[10px] font-semibold leading-5 text-[#8A6D2B]">
            {config?.note ??
              "Readings produced here are simulated DEMO DATA, not measurements from physical hardware."}
          </p>

          {/* Configurable channel values */}
          <section className="space-y-3 rounded-[22px] border border-[#DCE6DF] bg-white p-4">
            <h2 className="text-[13px] font-extrabold text-[#213D2F]">
              Configurable channel values
            </h2>
            <p className="text-[9px] leading-4 text-[#84938B]">
              Leave a field blank to draw a realistic random value from the model's training range.
            </p>
            <div className="grid grid-cols-2 gap-3">
              {Object.entries(channels).map(([channel, spec]) => (
                <label key={channel} className="block">
                  <span className="mb-1.5 flex items-baseline justify-between">
                    <span className="text-[10px] font-bold text-[#52675B]">{channel}</span>
                    <span className="text-[8px] text-[#9AA79F]">
                      {spec.min}–{spec.max} {spec.unit}
                    </span>
                  </span>
                  <input
                    type="number"
                    value={overrides[channel] ?? ""}
                    onChange={(e) => setOverride(channel, e.target.value)}
                    placeholder={String(Math.round((spec.min + spec.max) / 2))}
                    className="h-10 w-full rounded-xl border border-[#DDE6DF] bg-white px-3 text-[12px] text-[#203B2D] outline-none focus:border-[#76A58A]"
                  />
                </label>
              ))}
            </div>
            <div className="grid grid-cols-2 gap-3">
              <label className="block">
                <span className="mb-1.5 block text-[10px] font-bold text-[#52675B]">
                  Noise ± fraction (0–1)
                </span>
                <input
                  type="number"
                  min="0"
                  max="1"
                  step="0.05"
                  value={noise}
                  onChange={(e) => setNoise(e.target.value)}
                  className="h-10 w-full rounded-xl border border-[#DDE6DF] bg-white px-3 text-[12px] text-[#203B2D] outline-none focus:border-[#76A58A]"
                />
              </label>
              <label className="block">
                <span className="mb-1.5 block text-[10px] font-bold text-[#52675B]">
                  Seed (optional, reproducible)
                </span>
                <input
                  type="number"
                  min="0"
                  value={seed}
                  onChange={(e) => setSeed(e.target.value)}
                  placeholder="e.g. 42"
                  className="h-10 w-full rounded-xl border border-[#DDE6DF] bg-white px-3 text-[12px] text-[#203B2D] outline-none focus:border-[#76A58A]"
                />
              </label>
            </div>

            {/* Failure injection */}
            <div>
              <p className="mb-1.5 text-[10px] font-bold text-[#52675B]">
                Simulate sensor failure
              </p>
              <div className="flex flex-wrap gap-1.5">
                {Object.keys(channels).map((channel) => (
                  <button
                    key={channel}
                    onClick={() => toggleFail(channel)}
                    className={`rounded-full px-2.5 py-1 text-[9px] font-extrabold transition ${
                      failed.includes(channel)
                        ? "bg-[#FCE9E5] text-[#A55243]"
                        : "border border-[#DDE6DF] bg-white text-[#52675B]"
                    }`}
                  >
                    {channel}
                  </button>
                ))}
                <button
                  onClick={() => setFailed(failed.length ? [] : Object.keys(channels))}
                  className="rounded-full bg-[#FCE9E5] px-2.5 py-1 text-[9px] font-extrabold text-[#A55243]"
                >
                  {failed.length ? "Clear failures" : "Fail all"}
                </button>
              </div>
            </div>

            <div className="flex flex-wrap gap-2">
              <ModuleButton onClick={generate} disabled={generating}>
                <ModuleIcon name="signal" size={16} />
                {generating ? "Generating…" : "Generate demo reading"}
              </ModuleButton>
            </div>
            {error && (
              <p className="rounded-xl bg-[#FCE9E5] p-3 text-[10px] font-semibold leading-5 text-[#9D4C3E]">
                {error}
              </p>
            )}
          </section>

          {/* Generated reading */}
          {reading && <DemoReadingCard reading={reading} />}

          {/* Optional persistence */}
          {reading && (
            <section className="space-y-3 rounded-[22px] border border-[#DCE6DF] bg-white p-4">
              <h2 className="text-[13px] font-extrabold text-[#213D2F]">
                Store this reading (optional)
              </h2>
              <p className="text-[9px] leading-4 text-[#84938B]">
                Stored with <b>is_demo = true</b> against one of your devices. It never overwrites
                real sensor records, and real readings never show it in the connected-sensor view.
              </p>
              {devices.length === 0 ? (
                <p className="text-[10px] text-[#8A6D2B]">
                  No devices paired yet. Add one in Device Management to store demo rows.
                </p>
              ) : (
                <div className="flex flex-wrap items-end gap-2">
                  <div className="min-w-[160px] flex-1">
                    <SelectField
                      label="Device"
                      value={persistDeviceId}
                      onChange={setPersistDeviceId}
                      options={["", ...devices.map((d) => d.id)]}
                    />
                  </div>
                  <ModuleButton secondary onClick={persist} disabled={persisting}>
                    {persisting ? "Storing…" : "Store as demo"}
                  </ModuleButton>
                </div>
              )}
              {persistNote && (
                <p
                  className={`rounded-xl p-3 text-[10px] font-semibold leading-5 ${
                    persistNote.tone === "ok"
                      ? "bg-[#EAF6EF] text-[#1D4A33]"
                      : "bg-[#FCE9E5] text-[#9D4C3E]"
                  }`}
                >
                  {persistNote.text}
                </p>
              )}
            </section>
          )}
        </>
      ) : (
        <RealReadings loading={realData.loading} error={realData.error} items={realReadings} />
      )}
    </div>
  );
}

function DemoReadingCard({ reading }) {
  const entries = Object.entries(reading.reading ?? {});
  return (
    <section className="space-y-3 rounded-[22px] border border-[#F2DCB0] bg-[#FFFBF0] p-4">
      <div className="flex items-center justify-between">
        <h3 className="text-[13px] font-extrabold text-[#8A6D2B]">{reading.label}</h3>
        <span className="rounded-full bg-white px-2.5 py-1 text-[9px] font-extrabold uppercase tracking-[.06em] text-[#916112]">
          Simulated
        </span>
      </div>
      <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
        {entries.map(([channel, value]) => (
          <div key={channel} className="rounded-2xl border border-[#F2DCB0] bg-white p-3">
            <p className="text-[9px] font-bold uppercase tracking-[.06em] text-[#8A998F]">
              {channel}
            </p>
            <p className="mt-1 text-[15px] font-extrabold text-[#213D2F]">{value}</p>
          </div>
        ))}
        {reading.failed_channels?.map((channel) => (
          <div key={channel} className="rounded-2xl border border-[#F3C9C1] bg-white p-3">
            <p className="text-[9px] font-bold uppercase tracking-[.06em] text-[#8A998F]">
              {channel}
            </p>
            <p className="mt-1 text-[13px] font-extrabold text-[#A55243]">no signal</p>
          </div>
        ))}
      </div>
      <div className="flex flex-wrap gap-2 text-[9px] text-[#8A6D2B]">
        <span className="rounded-full bg-white px-2.5 py-1 font-extrabold">
          Generated {new Date(reading.generated_at).toLocaleTimeString()}
        </span>
        {reading.seed != null && (
          <span className="rounded-full bg-white px-2.5 py-1 font-extrabold">
            seed {reading.seed}
          </span>
        )}
        {reading.failed_channels?.length > 0 && (
          <span className="rounded-full bg-white px-2.5 py-1 font-extrabold">
            {reading.failed_channels.length} failed channel(s)
          </span>
        )}
      </div>
      <ul className="space-y-1">
        {reading.notes?.map((n, i) => (
          <li key={i} className="text-[9px] leading-4 text-[#8A6D2B]">
            • {n}
          </li>
        ))}
      </ul>
    </section>
  );
}

function RealReadings({ loading, error, items }) {
  if (loading) {
    return (
      <div className="space-y-3">
        {[1, 2, 3].map((n) => (
          <div key={n} className="h-16 animate-pulse rounded-[20px] bg-[#E8F0EB]" />
        ))}
      </div>
    );
  }
  if (error) {
    return (
      <p className="rounded-2xl bg-[#FCE9E5] p-4 text-[11px] font-semibold text-[#9D4C3E]">
        Could not load connected-sensor readings{error.status ? ` (${error.status})` : ""}.
      </p>
    );
  }
  return (
    <section className="overflow-hidden rounded-[22px] border border-[#E0E8E2] bg-white">
      {items.length === 0 ? (
        <p className="p-6 text-center text-[12px] text-[#7B8C82]">
          No real sensor readings yet. Readings you simulate in Demo mode are stored separately and
          will not appear here.
        </p>
      ) : (
        items.map((item, index) => (
          <div
            key={item.id}
            className={`flex items-center gap-3 p-4 ${index ? "border-t border-[#EDF1EE]" : ""}`}
          >
            <span className="grid h-10 w-10 place-items-center rounded-xl bg-[#E5F3F7] text-[#28778A]">
              <ModuleIcon name="device" size={18} />
            </span>
            <span className="min-w-0 flex-1">
              <b className="block text-[11px] text-[#294234]">
                {summarise(item)}
              </b>
              <span className="text-[9px] text-[#829188]">
                {item.created_at ? new Date(item.created_at).toLocaleString() : ""}
                {item.device_id ? ` · ${item.device_id.slice(0, 8)}` : ""}
              </span>
            </span>
            <b className="text-[9px] font-extrabold text-[#557064]">REAL</b>
          </div>
        ))
      )}
    </section>
  );
}

function summarise(item) {
  const parts = [];
  if (item.temperature != null) parts.push(`${item.temperature}°C`);
  if (item.humidity != null) parts.push(`${item.humidity}% RH`);
  if (item.soil_moisture != null) parts.push(`moisture ${item.soil_moisture}%`);
  if (item.ph != null) parts.push(`pH ${item.ph}`);
  return parts.length ? parts.join(" · ") : "Reading recorded";
}
